class AirwaySegmentModel {
  const AirwaySegmentModel({
    required this.seq,
    required this.ident,
    required this.lat,
    required this.lon,
    required this.dir,
    required this.level,
    required this.base,
    required this.top,
  });

  final int seq;
  final String ident;
  final double lat;
  final double lon;
  final String dir;
  final String level;
  final int base;
  final int top;

  factory AirwaySegmentModel.fromCompactList(List<dynamic> list, int seqIndex) {
    return AirwaySegmentModel(
      seq: seqIndex,
      ident: list[0]?.toString() ?? '',
      lat: 0.0,
      lon: 0.0,
      dir: list[1]?.toString() ?? '',
      level: '2',
      base: int.tryParse(list[2]?.toString() ?? '0') ?? 0,
      top: int.tryParse(list[3]?.toString() ?? '0') ?? 0,
    );
  }
}

class HighAirwayData {
  HighAirwayData._();

  static final Map<String, List<AirwaySegmentModel>> _cache =
      <String, List<AirwaySegmentModel>>{};

  static List<AirwaySegmentModel>? getAirway(String keyName) {
    final String key = keyName.trim().toUpperCase();
    if (key.isEmpty) return null;

    final dynamic dataList = _airways[key];
    if (dataList == null || dataList is! List) return null;

    return _cache.putIfAbsent(
      key,
      () {
        int seqCounter = 1;
        return (dataList as List)
            .map((data) =>
                AirwaySegmentModel.fromCompactList(data as List, seqCounter++))
            .toList();
      },
    );
  }

